class Solution {
  public long minimumCost(
      String source, String target, String[] original, String[] changed, int[] cost) {
    Map<String, Integer> id = new HashMap<>();
    for (String s : original) id.putIfAbsent(s, id.size());
    for (String s : changed) id.putIfAbsent(s, id.size());
    int size = id.size();
    final long INF = Long.MAX_VALUE / 4;
    long[][] dist = new long[size][size];
    for (long[] row : dist) Arrays.fill(row, INF);
    for (int i = 0; i < size; i++) dist[i][i] = 0;
    Set<Integer> lengths = new TreeSet<>();
    for (int i = 0; i < cost.length; i++) {
      int a = id.get(original[i]), b = id.get(changed[i]);
      dist[a][b] = Math.min(dist[a][b], cost[i]);
      lengths.add(original[i].length());
    }
    for (int k = 0; k < size; k++) {
      for (int i = 0; i < size; i++) {
        if (dist[i][k] == INF) continue;
        for (int j = 0; j < size; j++) {
          if (dist[k][j] != INF) dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);
        }
      }
    }
    int n = source.length();
    long[] dp = new long[n + 1];
    Arrays.fill(dp, INF);
    dp[0] = 0;
    for (int i = 0; i < n; i++) {
      if (dp[i] == INF) continue;
      if (source.charAt(i) == target.charAt(i)) dp[i + 1] = Math.min(dp[i + 1], dp[i]);
      for (int len : lengths) {
        if (i + len > n) break;
        Integer a = id.get(source.substring(i, i + len)), b = id.get(target.substring(i, i + len));
        if (a != null && b != null && dist[a][b] < INF)
          dp[i + len] = Math.min(dp[i + len], dp[i] + dist[a][b]);
      }
    }
    return dp[n] == INF ? -1 : dp[n];
  }
}
